38	async function startServer() {
39	    try {
40	        let pgvectorReady = false;
41	        try {
42	            await db.sequelize.query('CREATE EXTENSION IF NOT EXISTS vector');
43	            pgvectorReady = true;
44	        } catch (extErr) {
45	            console.warn("WARNING: pgvector not available — migrating faceVector to FLOAT[].");
46	            // The column may exist as 'vector' type; drop it so sync can recreate as FLOAT[]
47	            try {
48	                await db.sequelize.query(`
49	                    ALTER TABLE "users"
50	                    DROP COLUMN IF EXISTS "faceVector";
51	                `);
52	            } catch (dropErr) {
53	                // Table may not exist yet — that's fine, sync will create it
54	            }
55	        }
56	
57	        const modelNames = Object.keys(db).filter(
58	            k => k !== 'sequelize' && k !== 'Sequelize'
59	        );
60	        const failedModels = [];
61	
62	        for (const name of modelNames) {
63	            try {
64	                await db[name].sync({ alter: true });
65	                console.log(`  ✔ Synced: ${name}`);
66	            } catch (syncErr) {
67	                failedModels.push(name);
68	                console.error(`  ✖ Failed to sync ${name}:`, syncErr.message);
69	            }
70	        }
71	
72	        if (failedModels.length > 0) {
73	            console.warn(`\nWARNING: ${failedModels.length} model(s) failed to sync: ${failedModels.join(', ')}`);
74	            console.warn("The server will start, but those tables may be missing or outdated.\n");
75	        }
76	
77	        let port = process.env.APP_PORT || 5000;
78	        app.listen(port, '127.0.0.1', () => {
79	            console.log("--------------------------------------------------");
80	            console.log(`FlowGuard Server is FULLY READY on port ${port}`);
81	            console.log("--------------------------------------------------");
82	        });
83	    } catch (err) {
84	        console.error("Database Sync Error: ", err);
85	    }
86	}
87	
88	startServer();
