3	const verifyToken = (req, res, next) => {
4	    // 1. Grab the token from the request header
5	    const authHeader = req.headers['authorization'];
6	    
7	    // Tokens usually come in as "Bearer <token_string>", so we split it to just get the string
8	    const token = authHeader && authHeader.split(' ')[1]; 
9	
10	    // 2. If there is no token, kick them out
11	    if (!token) {
12	        return res.status(401).json({ message: "Access Denied. No security token provided." });
13	    }
14	
15	    try {
16	        // 3. Verify the token using your secret key
17	        const decoded = jwt.verify(token, process.env.APP_SECRET);
18	        
19	        // 4. Attach the decoded user data (like their ID) to the request
20	        req.user = decoded; 
21	        
22	        // 5. Let them through to the actual route!
23	        next(); 
24	
25	    } catch (err) {
26	        return res.status(403).json({ message: "Invalid or expired security token." });
27	    }
28	};
29	
30	module.exports = { verifyToken };

