33	router.post("/register", async (req, res) => {
34	    const { recaptchaToken, ...userData } = req.body;
35	    try {
36	        if (!recaptchaToken) return res.status(400).json({ errors: ["Security token missing."] });
37	
38	        // 1. reCAPTCHA Verification
39	        const params = new URLSearchParams();
40	        params.append('secret', process.env.RECAPTCHA_SECRET_KEY);
41	        params.append('response', recaptchaToken);
42	
43	        const googleResponse = await axios.post('https://www.google.com/recaptcha/api/siteverify', params, {
44	            headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
45	        });
46	
47	        if (!googleResponse.data.success || googleResponse.data.score < 0.5) {
48	            return res.status(403).json({ errors: ["Security check failed. Please try again."] });
49	        }
50	
51	        // 2. Data Validation
52	        let validationSchema = yup.object({
53	            name: yup.string().trim().required("Full name is required"),
54	            email: yup.string().trim().email("Invalid email format").required("Email is required"),
55	            password: yup.string().trim().min(8, "Password must be at least 8 characters").required(),
56	            role: yup.string().oneOf(['FM', 'Tenant', 'Staff']).required("Role is required"),
57	            tenantCode: yup.string().required("Access code is required")
58	        });
59	
60	        let validatedData = await validationSchema.validate(userData, { abortEarly: false });
61	
62	        // --- 3. THE SECURITY GATE ---
63	
64	        // BLOCK A: Prevent anyone from registering as FM publicly
65	        if (validatedData.role === 'FM') {
66	            return res.status(403).json({ errors: ["Administrative accounts cannot be created publicly."] });
67	        }
68	
69	        // BLOCK B: Tenant Registration (One-Time Invite Check)
70	        if (validatedData.role === 'Tenant') {
71	            const invite = await Invite.findOne({
72	                where: { code: validatedData.tenantCode, role: 'Tenant', isUsed: false }
73	            });
74	
75	            if (!invite) {
76	                return res.status(401).json({ errors: ["Invalid or used Invitation Code. Contact the FM office."] });
77	            }
78	
79	            // Check Expiration (e.g., 24h/48h set when invite was created)
80	            if (new Date() > invite.expiresAt) {
81	                return res.status(401).json({ errors: ["This invitation code has expired."] });
82	            }
83	
84	            // Mark invite as used so it cannot be used again
85	            await invite.update({ isUsed: true });
86	        }
87	
88	        // BLOCK C: Staff Registration (Hybrid Security Logic)
89	        if (validatedData.role === 'Staff') {
90	            const employer = await User.findOne({
91	                where: { role: 'Tenant', companyCode: validatedData.tenantCode }
92	            });
93	
94	            if (!employer) {
95	                return res.status(400).json({ errors: ["Invalid Unit Registration Code. Contact your manager."] });
96	            }
97	
98	            // Time Expiration Check (48 Hours)
99	            const fortyEightHours = 48 * 60 * 60 * 1000;
100	            const isExpired = Date.now() - new Date(employer.codeCreatedAt).getTime() > fortyEightHours;
101	
102	            if (isExpired) {
103	                return res.status(401).json({ errors: ["This unit code has expired (48h limit). Ask your manager to refresh it."] });
104	            }
105	
106	            // Usage Limit Check (Capacity)
107	            if (employer.codeCurrentUsage >= employer.codeMaxUsage) {
108	                return res.status(401).json({ errors: ["Registration capacity reached for this unit."] });
109	            }
110	
111	            // Link Staff to Tenant and increment usage
112	            validatedData.managerId = employer.id;
113	            await employer.increment('codeCurrentUsage');
114	        }
115	
116	        // 4. Hash & Save
117	        validatedData.password = await bcrypt.hash(validatedData.password, 10);
118	        let result = await User.create(validatedData);
119	
120	        res.json({ message: "Account registered successfully.", id: result.id });
121	
122	    } catch (err) {
123	        console.error("Registration Error Logic:", err);
124	        let errorMessages = [];
125	        if (err.name === 'SequelizeUniqueConstraintError') {
126	            errorMessages = ["This email is already registered in our system."];
127	        } else if (err.errors) {
128	            errorMessages = err.errors.map(e => (typeof e === 'object' ? e.message : e));
129	        } else {
130	            errorMessages = [err.message || "An unexpected system error occurred."];
131	        }
132	        res.status(400).json({ errors: errorMessages });
133	    }
134	});
