8	  const canvasRef = useRef(null);
9	  const navigate = useNavigate();
10	  const [searchParams] = useSearchParams();
11	
12	  const [enrollmentMode, setEnrollmentMode] = useState('camera'); // 'camera' | 'upload'
13	  const [stage, setStage] = useState('front'); // 'front', 'left', 'right', 'ready'
14	  const [photos, setPhotos] = useState({ front: null, left: null, right: null });
15	  const [loading, setLoading] = useState(false);
16	  const [errorMessage, setErrorMessage] = useState(null);
17	
18	  const token = localStorage.getItem("accessToken");
19	  const userName = localStorage.getItem("userName");
20	  const targetUserId = searchParams.get("userId");
